// STAGE 1: Quality Gate — Filter bad leads before spending AI credits
const leads = $input.first().json.leads;
const product = $input.first().json.product;
const tone = $input.first().json.tone;
const tenantId = $input.first().json.tenant_id;

const qualified = leads.filter(lead => {
  // Must have email
  if (!lead.email) return false;
  // Must have company or domain
  if (!lead.company && !lead.domain) return false;
  // Filter obvious invalid emails
  if (lead.email.includes('noreply') || lead.email.includes('info@')) return false;
  // Must have verification status = valid or accept-all
  if (lead.verification_status === 'invalid') return false;
  return true;
});

console.log(`Quality gate: ${leads.length} leads → ${qualified.length} qualified`);

return qualified.map(lead => ({
  json: { ...lead, product, tone, tenantId }
}));

