// STAGE 4: Assemble final personalized email data
const lead = $('quality-gate').item.json;
const claudeResponse = $('claude-writer').item.json;
const deepseekResponse = $('deepseek-hook').item.json;

// Extract Claude first line
let firstLine = '';
try {
  const content = claudeResponse.content;
  if (Array.isArray(content)) {
    firstLine = content.find(c => c.type === 'text')?.text || '';
  } else {
    firstLine = content || '';
  }
} catch(e) {
  firstLine = `Noticed ${lead.company} is doing interesting work in your space.`;
}

// Extract DeepSeek hook
let hook = {};
try {
  const dsContent = deepseekResponse.choices?.[0]?.message?.content || '{}';
  hook = JSON.parse(dsContent.replace(/```json|```/g, '').trim());
} catch(e) {
  hook = { hook: '', pain_point: '' };
}

// Score the first line quality
const qualityScore = (
  (firstLine.length > 10 && firstLine.length < 150 ? 30 : 0) +
  (firstLine.includes(lead.company) ? 25 : 0) +
  (!firstLine.toLowerCase().startsWith('i ') ? 20 : 0) +
  (!firstLine.includes('I came across') ? 15 : 0) +
  (firstLine.split(' ').length <= 25 ? 10 : 0)
);

return [{
  json: {
    email: lead.email,
    first_name: lead.first_name,
    last_name: lead.last_name,
    company: lead.company,
    title: lead.title,
    ai_first_line: firstLine.trim(),
    ai_hook: hook.hook || '',
    ai_pain_point: hook.pain_point || '',
    quality_score: qualityScore,
    product: lead.product,
    tenant_id: lead.tenantId,
    generated_at: new Date().toISOString()
  }
}];
